  function normalizeBirthTime(value){
    const raw=String(value??'').normalize('NFKC').replace(/\s+/g,'');
    let match=/^(\d{1,2})$/.exec(raw);
    if(!match)match=/^(\d{1,2}):(\d{1,2})$/.exec(raw);
    if(!match)match=/^(\d{1,2})(?:点|时)(?:(\d{1,2})分?)?$/.exec(raw);
    if(!match)throw Error('请输入小时和分钟，例如 06:30 或 6点30分，不需要秒。');
    const hour=Number(match[1]),minute=Number(match[2]??0);
    if(hour>23||minute>59)throw Error('时间需要在 00:00–23:59 之间，请核对小时和分钟。');
    return String(hour).padStart(2,'0')+':'+String(minute).padStart(2,'0');
  }
  function normalizeBirthDate(year,month,day,calendar){
    const y=String(year??'').normalize('NFKC').trim(),m=String(month??'').trim(),d=String(day??'').trim();
    if(!/^\d{4}$/.test(y)||!/^\d{1,2}$/.test(m)||!/^\d{1,2}$/.test(d))throw Error('请填写完整的出生年、月、日。');
    const yy=Number(y),mm=Number(m),dd=Number(d);
    if(yy<1900||yy>new Date().getFullYear()||mm<1||mm>12||dd<1||dd>(calendar==='lunar'?30:31))throw Error('请核对出生年、月、日。');
    if(calendar!=='lunar'){const date=new Date(Date.UTC(yy,mm-1,dd));if(date.getUTCFullYear()!==yy||date.getUTCMonth()!==mm-1||date.getUTCDate()!==dd)throw Error('这个公历日期不存在，请核对月和日。');}
    return y+'-'+String(mm).padStart(2,'0')+'-'+String(dd).padStart(2,'0');
  }
