  function privateZodiacReason(zodiac){
    const pair=['鼠牛','虎猪','兔狗','龙鸡','蛇猴','马羊'].find(g=>g.includes(zodiac)),group=['猴鼠龙','猪兔羊','虎马狗','蛇鸡牛'].find(g=>g.includes(zodiac));
    if(!zodiac||!pair||!group)return '';
    const partner=[...pair].filter(x=>x!==zodiac).join('、'),others=[...group].filter(x=>x!==zodiac).join('、');
    return `<details class="surface private-zodiac-reason"><summary>相合的生肖：<strong>${esc(partner)}</strong>、<strong>${esc(others)}</strong><span>仅自己可见</span></summary><p><strong>六合 · ${esc(partner)}</strong>　传统地支把十二生肖两两分为六组，你和${esc(partner)}同组。</p><p><strong>三合 · ${esc(others)}</strong>　${esc([...group].join('、'))}同属一个三合组。</p><p class="fine-print">文化参考，不保证相处结果。</p></details>`;
  }
