  function captureGuestProfile(){
    const form=$('#profile-form');if(!form||state.user&&!state.guestProfileDraft)return;
    const f=new FormData(form),data={fields:{},visibility:{},hobbies:[],listed:false,contactConsent:false};
    for(const key of ['nickname','city','intent','bio','contact','constellation','mbti'])data[key]=String(f.get(key)||'');
    for(const key of Object.keys(fieldLabels)){data.fields[key]=String(f.get('field_'+key)||'');data.visibility[key]=f.get('scope_'+key)||'private';}
    data.purposes=f.getAll('purposes');data.expectations=readExpectations(f);data.matchingConsent=readMatchingConsent(f);
    for(const key of ['dayMaster','zodiac','constellation','mbti'])data.visibility[key]=f.get('scope_'+key)||'private';
    for(const key of ['targetStems','targetZodiacs','targetConstellations','targetMbtis'])data[key]=f.getAll(key);
    data.dateActivities=f.getAll('dateActivities');
    data.hobbies=[...new Set([...f.getAll('hobbies'),...String(f.get('otherHobbies')||'').split(/[,，、]/).map(x=>x.trim()).filter(Boolean)])];
    try{if($('#availability-slots'))data.availability=readAvailability();if($('#residence-query'))data.residence=readResidenceDraft();}catch{}state.guestProfileDraft={data,ownerId:state.user?.id||null};
  }
  function profileProgress(form){
    const el=$('#pe-progress');if(!el||!form)return;const f=new FormData(form),filled=name=>String(f.get(name)||'').trim()!=='';
    const need=[['昵称',filled('nickname')],['城市',filled('city')],['认识目的',f.getAll('purposes').length>0],['约会想做的事',f.getAll('dateActivities').length>0],['爱好',f.getAll('hobbies').length>0||filled('otherHobbies')],['想认识的日主',f.getAll('targetStems').length>0],['想认识的生肖',f.getAll('targetZodiacs').length>0],['本人资料确认',f.has('consent')],['同意资料存储在香港',f.has('crossBorderConsent')],['同意隐私说明和条款',f.has('policyConsent')]];
    const left=need.filter(([,ok])=>!ok).map(([k])=>k);
    // Already public: the two confirmations are asked on every save, so they are not "missing" — only real gaps are.
    if(state.profile?.listed){const gaps=left.filter(k=>k!=='本人资料确认'&&k!=='同意隐私说明和条款');el.hidden=!gaps.length;el.classList.toggle('is-done',!gaps.length);el.innerHTML=gaps.length?`有 <b>${gaps.length}</b> 项待补：${esc(gaps.join('、'))}。补好保存后生效。`:'';return;}
    el.hidden=false;el.classList.toggle('is-done',!left.length);
    el.innerHTML=left.length?`还差 <b>${left.length}</b> 项必填就能公开：${esc(left.join('、'))}。其余都可以以后再补。`:'必填项都填好了，保存后就能公开。';
  }
