    const gap=fixedBottom-y;
    if(caption&&!captionDone&&gap>=88){const lines=wrap('“'+caption+'”',34,W-200,gap>=170?2:1,SERIF,500);const top=y+(gap-lines.length*52)/2+34;lines.forEach((l,i)=>put(l,W/2,top+i*52,34,soft,W-200,500,SERIF,'center'));}
