  function zipStore(entries){
    const encoder=new TextEncoder(),parts=[],directory=[];let offset=0,centralSize=0;
    const crc=data=>{let value=0xffffffff;for(const byte of data){value^=byte;for(let bit=0;bit<8;bit++)value=(value>>>1)^((value&1)?0xedb88320:0);}return (value^0xffffffff)>>>0;};
    for(const entry of entries){const name=encoder.encode(entry.name),sum=crc(entry.data),header=new Uint8Array(30+name.length),view=new DataView(header.buffer);view.setUint32(0,0x04034b50,true);view.setUint16(4,20,true);view.setUint16(6,0x0800,true);view.setUint16(12,0x21,true);view.setUint32(14,sum,true);view.setUint32(18,entry.data.length,true);view.setUint32(22,entry.data.length,true);view.setUint16(26,name.length,true);header.set(name,30);parts.push(header,entry.data);const central=new Uint8Array(46+name.length),record=new DataView(central.buffer);record.setUint32(0,0x02014b50,true);record.setUint16(4,20,true);record.setUint16(6,20,true);record.setUint16(8,0x0800,true);record.setUint16(14,0x21,true);record.setUint32(16,sum,true);record.setUint32(20,entry.data.length,true);record.setUint32(24,entry.data.length,true);record.setUint16(28,name.length,true);record.setUint32(42,offset,true);central.set(name,46);directory.push(central);centralSize+=central.length;offset+=header.length+entry.data.length;}
    const end=new Uint8Array(22),view=new DataView(end.buffer);view.setUint32(0,0x06054b50,true);view.setUint16(8,entries.length,true);view.setUint16(10,entries.length,true);view.setUint32(12,centralSize,true);view.setUint32(16,offset,true);return new Blob([...parts,...directory,end],{type:'application/zip'});
  }
